<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import AppModal from '../../components/conservation/AppModal.vue'
import { conservationStore, speciesForPlant } from '../../data/conservation'
type ReportHistory={id:string;type:string;period:string;generatedBy:string;generatedAt:string;format:string}
const form=reactive({type:'Biodiversity Summary',start:'2026-09-01',end:'2026-10-03',species:'',status:'',location:'',observationStatus:''}),preview=ref(false),toast=ref(''),viewing=ref<ReportHistory|null>(null),deleting=ref<ReportHistory|null>(null)
const history=ref<ReportHistory[]>([{id:'RPT001',type:'Biodiversity Summary',period:'1–30 Sep 2026',generatedBy:'Officer01',generatedAt:'1 Oct 2026, 09:00',format:'PDF'},{id:'RPT002',type:'Field Observation Report',period:'15–30 Sep 2026',generatedBy:'Officer01',generatedAt:'30 Sep 2026, 16:20',format:'CSV'}])
const observations=computed(()=>conservationStore.observations.filter(o=>(!form.species||speciesForPlant(o.plantId)?.id===form.species)&&(!form.observationStatus||o.status===form.observationStatus)&&(!form.location||o.location===form.location)))
function generate(){preview.value=true;history.value.unshift({id:`RPT${String(history.value.length+1).padStart(3,'0')}`,type:form.type,period:`${form.start} – ${form.end}`,generatedBy:'Officer01',generatedAt:'3 Oct 2026, 12:00',format:'Preview'});requestAnimationFrame(()=>document.querySelector('.report-preview')?.scrollIntoView({behavior:'smooth'}))}
function exportFile(format:string){toast.value=`${format} export is ready for backend integration.`;setTimeout(()=>toast.value='',2500)}
function remove(){if(deleting.value)history.value.splice(history.value.findIndex(r=>r.id===deleting.value?.id),1);deleting.value=null}
</script>
<template><section class="page-intro"><div><p class="page-kicker">ANALYSIS & EXPORT</p><h2>Reports</h2><p>Generate filtered period summaries from biodiversity records.</p></div></section><section class="panel"><header class="panel-header"><div><p class="section-kicker">A. GENERATE REPORT</p><h2>Report Filters</h2></div></header><form class="form-grid" @submit.prevent="generate"><label class="form-field"><span>Report Type</span><select v-model="form.type"><option>Biodiversity Summary</option><option>Species Report</option><option>Field Observation Report</option><option>Conservation Status Report</option></select></label><label class="form-field"><span>Species</span><select v-model="form.species"><option value="">All species</option><option v-for="s in conservationStore.species" :key="s.id" :value="s.id">{{s.scientificName}}</option></select></label><label class="form-field"><span>Start Date</span><input v-model="form.start" type="date" required /></label><label class="form-field"><span>End Date</span><input v-model="form.end" type="date" required /></label><label class="form-field"><span>Conservation Status</span><select v-model="form.status"><option value="">All statuses</option><option v-for="s in [...new Set(conservationStore.species.map(x=>x.status))]" :key="s">{{s}}</option></select></label><label class="form-field"><span>Location</span><select v-model="form.location"><option value="">All locations</option><option v-for="l in [...new Set(conservationStore.observations.map(o=>o.location))]" :key="l">{{l}}</option></select></label><label class="form-field"><span>Observation Status</span><select v-model="form.observationStatus"><option value="">All statuses</option><option v-for="s in ['Approved','Pending Review','Rejected','Correction Required','Flagged']" :key="s">{{s}}</option></select></label><div class="form-field"><span>&nbsp;</span><button class="primary-button">Generate Report</button></div></form>
<article v-if="preview" class="report-preview"><header class="report-title"><p class="section-kicker">NIAH NATIONAL PARK</p><h2>{{form.type}}</h2></header><p class="report-meta">Reporting period: {{form.start}} to {{form.end}} · Species: {{form.species||'All'}} · Location: {{form.location||'All'}}</p><div v-if="form.type==='Biodiversity Summary'" class="metric-grid"><div class="metric"><span>Total Plant Records</span><strong>{{conservationStore.plants.length}}</strong></div><div class="metric"><span>Unique Species</span><strong>{{conservationStore.species.length}}</strong></div><div class="metric"><span>New Records</span><strong>5</strong></div><div class="metric"><span>Approved Observations</span><strong>{{observations.filter(o=>o.status==='Approved').length}}</strong></div><div class="metric"><span>Pending Observations</span><strong>{{observations.filter(o=>o.status==='Pending Review').length}}</strong></div></div><div v-else-if="form.type==='Species Report'" class="table-scroll"><table><thead><tr><th>Scientific Name</th><th>Common Name</th><th>Family</th><th>Status</th><th>Plants</th><th>First Recorded</th><th>Latest Record</th><th>Distribution</th><th>Photos</th></tr></thead><tbody><tr v-for="s in conservationStore.species.filter(x=>!form.species||x.id===form.species)" :key="s.id"><td><em>{{s.scientificName}}</em></td><td>{{s.commonName}}</td><td>{{s.family}}</td><td>{{s.status}}</td><td>{{s.plantCount}}</td><td>1 Sep 2026</td><td>{{s.updated}}</td><td>{{s.distribution}}</td><td>{{s.plantCount+4}}</td></tr></tbody></table></div><div v-else-if="form.type==='Field Observation Report'"><div class="metric-grid"><div class="metric"><span>Total Observations</span><strong>{{observations.length}}</strong></div><div class="metric"><span>Approved</span><strong>{{observations.filter(o=>o.status==='Approved').length}}</strong></div><div class="metric"><span>Pending</span><strong>{{observations.filter(o=>o.status==='Pending Review').length}}</strong></div><div class="metric"><span>Rejected</span><strong>{{observations.filter(o=>o.status==='Rejected').length}}</strong></div></div><div class="table-scroll"><table><thead><tr><th>Observation</th><th>Plant</th><th>Species</th><th>Date</th><th>Status</th></tr></thead><tbody><tr v-for="o in observations" :key="o.id"><td>{{o.id}}</td><td>{{o.plantId}}</td><td>{{speciesForPlant(o.plantId)?.scientificName}}</td><td>{{o.observedAt}}</td><td>{{o.status}}</td></tr></tbody></table></div></div><div v-else class="metric-grid"><div v-for="s in [...new Set(conservationStore.species.map(x=>x.status))]" :key="s" class="metric"><span>{{s}}</span><strong>{{conservationStore.species.filter(x=>x.status===s).length}} species</strong><small>{{conservationStore.species.filter(x=>x.status===s).reduce((n,x)=>n+x.plantCount,0)}} plant records</small></div></div><div class="modal-actions"><button class="secondary-button" @click="exportFile('PDF')">Export PDF</button><button class="secondary-button" @click="exportFile('CSV')">Export CSV</button></div></article></section>
<section class="panel"><header class="panel-header"><div><p class="section-kicker">B. REPORT HISTORY</p><h2>Generated Reports</h2></div></header><div class="table-scroll"><table><thead><tr><th>Report ID</th><th>Report Type</th><th>Reporting Period</th><th>Generated By</th><th>Generated At</th><th>Format</th><th>Actions</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td><strong>{{r.id}}</strong></td><td>{{r.type}}</td><td>{{r.period}}</td><td>{{r.generatedBy}}</td><td>{{r.generatedAt}}</td><td><span class="badge approved">{{r.format}}</span></td><td><div class="action-group"><button class="action-button" @click="viewing=r">View</button><button class="action-button" @click="exportFile(r.format)">Download</button><button class="action-button danger" @click="deleting=r">Delete</button></div></td></tr></tbody></table></div></section><AppModal v-if="viewing" :title="viewing.type" :subtitle="viewing.id" @close="viewing=null"><dl class="detail-list"><div v-for="(v,k) in viewing" :key="k"><dt>{{k}}</dt><dd>{{v}}</dd></div></dl></AppModal><AppModal v-if="deleting" title="Delete report history?" :subtitle="deleting.id" @close="deleting=null"><p>This removes the generated report entry from frontend history.</p><div class="modal-actions"><button class="secondary-button" @click="deleting=null">Cancel</button><button class="danger-button" @click="remove">Delete</button></div></AppModal><div v-if="toast" class="toast">{{toast}}</div></template>
